properties.query:
let windowSize = 1h;

// S24: C2 Jam/Takeover — UAVDatalinkConn_CL엔 UAVId/SwarmId 없음(PeerIp 기준), 전역 게이트
let S24Time = toscalar(
    UAVDatalinkConn_CL
    | where TimeGenerated > ago(windowSize)
    | where State in ('jammed','disconnected','hijacked')
    | summarize min(TimeGenerated));

// S1: GNSS Spoofing — UAVTelemetry_CL엔 SwarmId 없음, 전역 게이트
let S1Time = toscalar(
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where MsgType == 'EKF_STATUS_REPORT' and PosHorizVariance > 5.0
    | summarize min(TimeGenerated));

// S108: Mesh Partition — UAVFleetInfra_CL, FleetId 사용, LinkA/LinkB/LinkStatus
let S108 =
    UAVFleetInfra_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotempty(LinkA) and isnotempty(LinkB) and LinkStatus != 'up'
    | extend Stage = 'S108', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S103: Collision Course — UAVFleetState_CL, FleetId 사용
let S103 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotempty(CollisionRiskPair)
    | extend Stage = 'S103', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

union S108, S103
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SwarmId
| extend HasS24 = isnotnull(S24Time), HasS1 = isnotnull(S1Time)
| extend EffectiveStageCount = StageCount + toint(HasS24) + toint(HasS1)
| where EffectiveStageCount >= 3
| extend CampaignType = "C26_분단격파_C2재밍_메시파티션_고립스푸핑_충돌"
| extend StepSummary = strcat("S24(전역)@", tostring(S24Time), " | S1(전역)@", tostring(S1Time), " | Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, SwarmId, StagesSeen, EffectiveStageCount, CampaignType, StepSummary, Severity
